"""Refresh existing canonical King knowledge sections without touching other features."""
import json
from sources import ROOT

def section(path,heading,body):
    p=ROOT/path;s=p.read_text(encoding='utf-8')
    if heading=='Source corpus working build — blocked' and '## Source corpus qualified runtime build' in s:heading='Source corpus qualified runtime build'
    start=s.index('## '+heading);end=s.find('\n## ',start+3)
    if end<0:end=len(s)
    s=s[:start]+'## '+heading+'\n'+body.strip()+'\n'+s[end:]
    s=s.replace('King corpus blocked working build','King qualified review-preview corpus')
    p.write_text(s,encoding='utf-8')

def main():
    manifest=json.loads((ROOT/'backend/src/main/resources/data/king/corpus/manifest.json').read_text(encoding='utf-8'));c=manifest['counts']
    summary=f"Qualified provider population: Reorder {c['REORDER']}, Reflex {c['REFLEX']} (13 families; minimum {min(manifest['families'].values())}), Explain {c['EXPLAIN']}, Conquest {c['CONQUEST']} boards; source-qualified lexicon {manifest['lexiconCount']}. Human approval and production ACTIVE remain zero."
    runtime='''KingCorpus verifies compressed checksums, source-lock, schema/build versions, logical content hashes, license shard class and provider floors, then shares indexed IDs and a 512-entry LRU decoded cache with 15-minute TTL. Two gzip SQLite shards under backend/src/main/resources/data/king/corpus/ are classpath resources, extracted to owned temporary files and opened read-only/immutable. Normal shutdown closes connections and removes those files. No raw corpus, working DB or internet truth dependency.
Server property king.content-channel selects PRODUCTION, REVIEW_PREVIEW or ENGINEERING. PRODUCTION is closed because no genuine ACTIVE owner manifest exists. REVIEW_PREVIEW uses only source-backed HIGH_CONFIDENCE_SOURCE_BACKED records with HUMAN_REVIEW_PENDING. ENGINEERING retains fixtures for tests and is prohibited in prod/production profiles. Blank channel resolves to PRODUCTION except the legacy explicitly enabled non-production engineering flag. Clients cannot select a trust channel.'''
    diversity='''KingRecentContent selects one deterministic sequence using the union of both human histories. Match semantic uniqueness never relaxes. Strong phrase/exact-sense suppression precedes weak lexeme suppression; compatible family/difficulty buckets rotate. Fallback relaxes weak lexemes, then phrase/concept history, then older semantic history in stable oldest-first order. Difficulty never exceeds the requested maximum. Insufficient unique content fails closed. Histories reserve assigned match IDs and persist across sessions for 6 hours; users are authenticated IDs, never session strings. LRU max 4096 users; semantic/phrase/concept/lexeme caps 192/96/96/96, hashes only. Idle histories expire and shutdown clears all state. This is process-local, not durable or multi-instance state.'''
    policy='''Core source derivatives use OEWN 2025 / Princeton WordNet, OANC, CEFR-J vocabulary/grammar and SCOWL US/GB. Kaikki raw English-edition Wiktextract snapshot 2026-09-28 is a separate CC BY-SA 4.0 phrase shard. Typed definitions/tags only; examples, quotations, translations, etymologies and media excluded. Current official Wikimedia terms evidence is under corpus/licenses/wiktionary-assessment.md. Unknown-license and validation-only sources, including existing EN-VI SQLite, never supply new gameplay truth. Runtime attribution, source lock and source notices ship beside both shards; preserve them on redistribution.'''
    review='''Qualification is deterministic source confidence, not linguistic perfection or owner approval. Source-annotated constituent chunks preserve noun phrases, auxiliary/verb chains, relatives and typed particles; safe adjunct/time alternatives are enumerated. Unproven separability/coordination/scoped-adverb cases remain quarantined. Phrase occurrences link exact expression identity without claiming a contextual phrase sense. Explain evaluates all learner senses, excludes capitalized source senses and explicit specialist-domain senses, uses same-synset aliases and exact source forms, and proves narrowing from hypernym to marked definition excerpt to full definition. Source glosses can still be formal. Some Reorder distribution goals remain below target; total/cap gates pass. UNKNOWN CEFR is retained; estimated difficulty is not direct CEFR. Review pack: docs/king-of-english/corpus/review/runtime-review.html; ambiguity examples are separate. Production promotion still requires a genuine owner manifest.'''
    verify='''Continuation evidence: docs/king-of-english/corpus/continuation/. Scoped King tests include actual artifact providers, all 16 REVIEW_PREVIEW broker flows, source/schema/checksum/license fail-closed mutations, cache bounds/TTL/LRU/cross-mode histories and 500 two-human mixed rooms. Separate artifact-only JVM starts in an empty temporary directory. Docker-backed Card Blast/Word Chain regressions passed with -Dapi.version=1.44. Frontend King/Games/Word Chain/auth/typecheck and real browser smoke use synthetic auth, real local engines; responsive checks at 390 and 1280. Physical touch, real-account production acceptance, subjective audio and production capacity remain unverified. No deployment, production DB, migration, auth, Turnstile or Cloudflare change.'''
    k='.claude/architecture/features/king-of-english.md'
    section(k,'Content contracts and quality',summary+'\n'+policy+'\n'+review)
    section(k,'Memory, persistence and config',runtime+'\n'+diversity+'\nRooms hold IDs, queues, scores, receipts and bounded mode state, never corpus copies. Single instance room cap 500; cleanup and history expiry are measured, with no production capacity claim. Durable result/learning/streak/leaderboard writes remain deferred.')
    section(k,'Source corpus working build — blocked','The continuation resolves the original qualification, runtime and diversity gaps.\n'+summary+'\nFinal acceptance evidence and exact commands: docs/king-of-english/corpus/continuation/FINAL_REPORT.md. No deployment has occurred.')
    p=ROOT/k;s=p.read_text(encoding='utf-8').replace('## Source corpus working build — blocked','## Source corpus qualified runtime build').replace('KingGame lazily imports KingArena; development gate;','KingGame lazily imports KingArena; server capability gate;');s=s.replace('- 2026-10-04: Locked/imported Tier A sources; canonical offline SQLite/candidates/150 boards; release blocked on linguistic/family floors and unfinished runtime integration.','- 2026-10-04: Continued the source corpus through qualification, separately licensed phrase shard, runtime providers, server preview channel, bounded cooldown, Docker/broker/frontend/browser and artifact-only JVM verification. Production remains closed.')
    p.write_text(s,encoding='utf-8')
    section(k,'Verification and limitations',verify+'\n'+review)
    section(k,'Gotchas and stop boundary','Single-instance only. Preview history is transient; deadlines continue during disconnect grace. Receipts and caches are bounded. This task stops before deployment. The next owner-authorized task may build/deploy REVIEW_PREVIEW only after checking continuation/verification-gate.json; production content remains inactive.\n'+review)
    section('.claude/architecture/03-backend.md','King source corpus offline boundary',summary+'\n'+runtime+'\n'+diversity)
    section('.claude/architecture/03-backend.md','King Of English integration',summary+'\n'+runtime+'\nOne synchronized KingService and four existing mode engines retain private projections, receipts/session/revision guards and unchanged scoring. Rooms cap 500; receipts 256, clues 8, guesses 12, Conquest used words 180. The shared LocalGameLexicon cache and Word Chain remain unchanged; preview Conquest uses artifact eligibility. Durable learning/results writes remain deferred.\n'+verify)
    section('.claude/architecture/08-cross-cutting.md','King corpus provenance boundary',policy+'\n'+runtime+'\n'+diversity)
    section('.claude/architecture/09-build-test-deploy.md','King source corpus build',summary+'\n'+policy+'''\nBuild from already checksum-verified caches: python -X utf8 backend/scripts/king/corpus/reproduce.py (derive → raw phrase ingest → full OANC collocation mining → qualify → two-shard artifact). Initial normalization/OANC/board evidence remains separately retained. Logical hashes must match a subsequent identical replay. Then run quality.py, review_preview.py and scoped test commands in continuation/FINAL_REPORT.md. Maven resources package the two gzip SQLite shards, manifest, sources.lock.json, ATTRIBUTION.md and licenses/ together. The next deployment uses canonical backend/frontend build wrappers from this Games worktree; no raw download or normalized DB at runtime. Explicit backend config: --king.content-channel=REVIEW_PREVIEW (or KING_CONTENT_CHANNEL=REVIEW_PREVIEW). Frontend must include current server capability gate; no client flag. Full production activation is not authorized.
'''+verify)
    section('.claude/architecture/05-api-catalog.md','King Of English — local Phase 4','Authenticated config/history/results and private STOMP namespace remain. Config additionally returns contentChannel, playEnabled, providerCounts and bundled attribution text under REVIEW_PREVIEW. Clients send no trust selection; extra contentChannel fields cannot change server selection. Playing projections include server contentChannel and engineering=false under preview. POS carries safe relative occurrence offsets; target/answers/aliases and board Echo paths remain private until role/resolution rules permit them. Existing receipt/session/auth guards and gameplay scoring are unchanged.\n'+summary)
    section('.claude/architecture/09-build-test-deploy.md','King Of English local verification/config',runtime+'\n'+verify+'\nRaw normalization/OANC adapters are replayed into an isolated verification DB by verify_normalization_replay.py; per-table logical hashes compare with the preserved canonical source tables. No production database is involved.')
    section('.claude/architecture/11-known-issues.md','King source corpus acceptance blockers','Original hard-floor/runtime/diversity gaps are resolved.\n'+summary+'\n'+review+'\n'+verify)
    section('.claude/architecture/features/dictionary-vocabulary.md','King corpus source policy',policy+'\nDictionary and Word Chain lookup behavior remain unchanged. REVIEW_PREVIEW Conquest validates against its source-qualified artifact lexicon instead of the validation-only EN-VI dictionary.\n'+summary)
    p=ROOT/'.claude/architecture/features/games.md';s=p.read_text(encoding='utf-8').replace('King Of English is the third title with local-development four modes / sixteen flows and','King Of English is the third title with server-controlled review-preview four modes / sixteen flows and');p.write_text(s,encoding='utf-8')
    p=ROOT/'.claude/architecture/06-frontend.md';s=p.read_text(encoding='utf-8');anchor='## King Of English integration\n';addition="KingGame reads authenticated server config through the canonical API client with cancellation; production NODE_ENV does not decide play availability. Source/license attribution is readable in the lobby, escaped as text. POS highlights the unique annotated occurrence using backend relative offsets. No accepted-answer bank or client trust selector.\n"
    if addition not in s:s=s.replace(anchor,anchor+addition)
    p.write_text(s,encoding='utf-8')
    p=ROOT/'.claude/PROJECT_CONTEXT_FOR_CHAT.md';s=p.read_text(encoding='utf-8').replace('King corpus local work (2026-10-04): pinned source ingestion/canonical candidates/quality gates; release blocked; no deployment.', 'King corpus continuation (2026-10-04): '+summary+' Runtime artifact/providers, server preview channel, bounded cross-mode histories and full scoped verification are implemented; no deployment.').replace('King corpus open: Reorder alternatives; Explain clue quality; nine Reflex family confidence floors; four runtime providers/channel; semantic cooldown; runtime memory verification. Review-preview deployment is not authorized by completion status.','King corpus implementation gaps resolved; source confidence is not owner approval. Review-preview readiness and exact build/config/license/test evidence: docs/king-of-english/corpus/continuation/FINAL_REPORT.md. Human pedagogy review, distribution goals, physical touch/real account checks remain disclosed. Deployment requires the next explicit owner-authorized task.')
    p.write_text(s,encoding='utf-8')
    print('CANONICAL_KB_UPDATED')

if __name__=='__main__':main()
